CREATE OR REPLACE FUNCTION stock_v2.guard_owner_charge()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'stock_v2'
AS $function$
declare s text; did bigint;
begin
 select d.status,d.document_id into s,did
 from stock_v2.document d join stock_v2.document_line l on l.document_id=d.document_id
 where l.line_id=(case when tg_op='DELETE' then old.document_line_id else new.document_line_id end) for update of d;
 if s is distinct from 'draft' then raise exception 'Posted ownership charges may only be corrected through approved reconciliation adjustments'; end if;
 if tg_op='DELETE' then return old; end if;
 return new;
end $function$

CREATE OR REPLACE FUNCTION stock_v2.guard_grv_line_price()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'stock_v2'
AS $function$
declare s text; did bigint; kind text; demo boolean;
begin
 select d.status,d.document_id,d.document_type,(i.item_code like 'DEMO_%') into s,did,kind,demo from stock_v2.document d join stock_v2.document_line l on l.document_id=d.document_id join stock_v2.item i on i.item_id=l.item_id where l.line_id=(case when tg_op='DELETE' then old.line_id else new.line_id end) for update of d;
 if tg_op='INSERT' and s='posted' and kind='opening' and demo and new.actual_unit_cost=10 and new.provisional_unit_cost is null then return new; end if;
 if s<>'draft' then raise exception 'Price changes to posted GRVs require the future admin pricing procedure'; end if;
 if tg_op='DELETE' then return old; end if;
 return new;
end $function$

CREATE OR REPLACE FUNCTION stock_v2.demo_post_multi_po_dnote(p_request uuid, p_data jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'stock_v2', 'pg_temp'
AS $function$
declare v_owner bigint; v_loc bigint; v_doc bigint; v_docline bigint; v_line jsonb; v_order_line bigint; v_item bigint; v_qty numeric; v_supplier text; v_prev jsonb; v_result jsonb; v_date date; v_ref text;
begin
 if p_data->>'owner_code' not in ('JS','AO') then raise exception 'Invalid test stock owner';end if;
 v_supplier:=btrim(coalesce(p_data->>'supplier',''));v_ref:=btrim(coalesce(p_data->>'delivery_note',''));v_date:=(p_data->>'receipt_date')::date;
 if v_supplier='' or v_ref='' or v_date is null then raise exception 'Supplier, D-Note and date required';end if;
 if not jsonb_typeof(p_data->'lines')='array' or jsonb_array_length(p_data->'lines')=0 then raise exception 'Select PO lines';end if;
 select owner_id into v_owner from stock_v2.owner where owner_code='TEST_'||(p_data->>'owner_code') and active;
 select location_id into v_loc from stock_v2.location where location_code='TEST_WH';
 if v_owner is null or v_loc is null then raise exception 'Test owner or warehouse missing';end if;
 perform pg_advisory_xact_lock(hashtextextended('stock-v2-dnote:'||v_owner||':'||v_supplier||':'||v_ref,0));
 if exists(select 1 from stock_v2.grv_detail g join stock_v2.document d using(document_id) join stock_v2.movement m on m.document_line_id in (select dl.line_id from stock_v2.document_line dl where dl.document_id=d.document_id) where g.supplier_name=v_supplier and g.delivery_note=v_ref and m.owner_id=v_owner and d.status='posted') then raise exception 'This supplier D-Note has already been received';end if;
 if exists(select 1 from stock_v2.document where document_number='DEMO-MULTIPO-'||p_request) then raise exception 'Request already posted';end if;
 insert into stock_v2.document(document_type,document_number,document_date,status,reason) values('grv','DEMO-MULTIPO-'||p_request,v_date,'draft','D-Note received against multiple POs') returning document_id into v_doc;
 insert into stock_v2.grv_detail(document_id,supplier_name,delivery_note,delivery_note_date,price_status) values(v_doc,v_supplier,v_ref,v_date,'pending');
 for v_line in select value from jsonb_array_elements(p_data->'lines') loop
  v_order_line:=(v_line->>'order_line_id')::bigint;v_qty:=(v_line->>'quantity')::numeric;
  if v_qty is null or v_qty<=0 or v_qty>100000 then raise exception 'Invalid received quantity';end if;
  select ol.item_id into v_item from stock_v2.order_line ol join stock_v2.order_header h using(order_id) where ol.order_line_id=v_order_line and h.owner_id=v_owner and h.status='approved' and h.supplier_name=v_supplier and ol.ordered_quantity-ol.received_quantity>=v_qty for update of ol;
  if v_item is null then raise exception 'PO line unavailable, wrong supplier or quantity too high';end if;
  if exists(select 1 from jsonb_array_elements(p_data->'lines') e where (e->>'order_line_id')::bigint=v_order_line group by (e->>'order_line_id') having count(*)>1) then raise exception 'Duplicate PO line';end if;
  insert into stock_v2.document_line(document_id,item_id,quantity,note) values(v_doc,v_item,v_qty,'D-Note received pending pricing') returning line_id into v_docline;
  insert into stock_v2.movement(document_line_id,owner_id,location_id,quantity_delta) values(v_docline,v_owner,v_loc,v_qty);
  update stock_v2.order_line set received_quantity=received_quantity+v_qty where order_line_id=v_order_line;
  insert into stock_v2.demo_grv_line_link(document_id,order_line_id,qty,received_unit_price) values(v_doc,v_order_line,v_qty,case when nullif(btrim(v_line->>'unit_price'),'') is not null then (v_line->>'unit_price')::numeric else null end);
  insert into stock_v2.grv_line_price(line_id,actual_unit_cost) values(v_docline,case when nullif(btrim(v_line->>'unit_price'),'') is not null then (v_line->>'unit_price')::numeric else null end);
 end loop;
 update stock_v2.document set status='posted',posted_at=now() where document_id=v_doc;
 return jsonb_build_object('document_id',v_doc,'status','posted','receipt_mode','dnote');
end; $function$

CREATE OR REPLACE FUNCTION stock_v2.demo_post_unplanned_dnote(p_request uuid, p_data jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'stock_v2', 'pg_temp'
AS $function$
declare v_owner bigint;v_supplier text;v_ref text;v_result jsonb;
begin
 if p_data->>'owner_code' not in ('JS','AO') then raise exception 'Invalid test stock owner';end if;
 v_supplier:=btrim(coalesce(p_data->>'supplier',''));v_ref:=btrim(coalesce(p_data->>'delivery_note',''));
 if v_supplier='' or v_ref='' then raise exception 'Supplier and delivery note required';end if;
 select owner_id into v_owner from stock_v2.owner where owner_code='TEST_'||(p_data->>'owner_code') and active;
 if v_owner is null then raise exception 'Stock owner unavailable';end if;
 perform pg_advisory_xact_lock(hashtextextended('stock-v2-dnote:'||v_owner||':'||v_supplier||':'||v_ref,0));
 if exists(select 1 from stock_v2.grv_detail g join stock_v2.document d using(document_id)
  join stock_v2.document_line dl using(document_id) join stock_v2.movement m on m.document_line_id=dl.line_id
  where g.supplier_name=v_supplier and g.delivery_note=v_ref and m.owner_id=v_owner and d.status='posted' and m.quantity_delta>0)
 then raise exception 'This supplier D-Note has already been received';end if;
 v_result:=stock_v2.demo_multi('direct_grv',p_request,p_data);
 return v_result;
end; $function$

CREATE OR REPLACE FUNCTION stock_v2.guard_grv_details()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'stock_v2'
AS $function$
declare s text; did bigint;
begin
 did:=case when tg_op='DELETE' then old.document_id else new.document_id end;
 select status into s from stock_v2.document where document_id=did for update;
 if s<>'draft' and tg_op<>'UPDATE' then raise exception 'Posted GRV detail locked'; end if;
 if s<>'draft' and tg_op='UPDATE' and (new.supplier_name<>old.supplier_name or new.delivery_note<>old.delivery_note or new.document_id<>old.document_id) then
   raise exception 'Posted GRV identity locked';
 end if;
 if tg_op='DELETE' then return old; end if;
 return new;
end $function$

CREATE OR REPLACE FUNCTION stock_v2.recalculate_costs(p_reason text)
 RETURNS bigint
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'stock_v2'
AS $function$
declare r record; q numeric(20,6); v numeric(26,8); avg_cost numeric(26,10);
 unit_price numeric(20,8); mv numeric(26,8); provisional_flag boolean; runkey bigint;
begin
 perform pg_advisory_xact_lock(hashtext('stock_v2_inventory_posting'));
 if exists(
  select 1 from stock_v2.document d where d.status='posted' and d.document_type not in ('opening','grv','issue','return')
 ) then raise exception 'Unsupported posted movement type for costing replay'; end if;
 if exists(
  select 1 from stock_v2.movement m join stock_v2.document_line dl on dl.line_id=m.document_line_id
  join stock_v2.document d on d.document_id=dl.document_id where d.status='posted' and
  d.document_type='return' and dl.source_line_id is null
 ) then raise exception 'Returns must reference original issue lines for costing'; end if;
 insert into stock_v2.cost_run(reason) values(p_reason) returning run_id into runkey;
 for r in
 select m.movement_id,m.quantity_delta,m.owner_id,m.location_id,
 dl.item_id,dl.line_id,dl.source_line_id,d.document_type,d.document_date,d.document_id,
 gp.actual_unit_cost,gp.provisional_unit_cost
 from stock_v2.movement m join stock_v2.document_line dl on dl.line_id=m.document_line_id
 join stock_v2.document d on d.document_id=dl.document_id
 left join stock_v2.grv_line_price gp on gp.line_id=dl.line_id
 where d.status='posted'
 order by dl.item_id,m.owner_id,d.document_date,d.document_id,m.movement_id
 loop
 select coalesce(sum(ce.movement_value),0),coalesce(sum(m2.quantity_delta),0)
 into v,q from stock_v2.cost_entry ce
 join stock_v2.movement m2 on m2.movement_id=ce.movement_id
 where ce.run_id=runkey and ce.item_id=r.item_id and ce.owner_id=r.owner_id;
 avg_cost:=case when q>0 then v/q else null end;
 provisional_flag:=false;
 if r.document_type in ('opening','grv') then
   unit_price:=coalesce(r.actual_unit_cost,r.provisional_unit_cost,avg_cost);
   if unit_price is null then raise exception 'Opening/GRV price missing with no existing WA for line %',r.line_id; end if;
   provisional_flag:=r.actual_unit_cost is null;
   mv:=r.quantity_delta*unit_price;
 elsif r.document_type='return' then
   select -ce.movement_value/m2.quantity_delta into unit_price
   from stock_v2.cost_entry ce join stock_v2.movement m2 on m2.movement_id=ce.movement_id
   join stock_v2.document_line l2 on l2.line_id=m2.document_line_id
   where ce.run_id=runkey and l2.line_id=r.source_line_id and m2.owner_id=r.owner_id
   order by ce.movement_id limit 1;
   if unit_price is null then raise exception 'Original issue not costed for return line %',r.line_id; end if;
   mv:=r.quantity_delta*unit_price;
 else
   if avg_cost is null then raise exception 'No weighted average for issue line %',r.line_id; end if;
   mv:=r.quantity_delta*avg_cost;
 end if;
 if q+r.quantity_delta < 0 then raise exception 'Cost replay negative stock at line %',r.line_id; end if;
 insert into stock_v2.cost_entry(run_id,movement_id,item_id,owner_id,quantity_after,value_after,unit_cost,movement_value,provisional)
 values(runkey,r.movement_id,r.item_id,r.owner_id,q+r.quantity_delta,v+mv,
 case when q+r.quantity_delta>0 then (v+mv)/(q+r.quantity_delta) else 0 end,mv,provisional_flag);
 end loop;
 update stock_v2.cost_run set status='complete',finished_at=now() where run_id=runkey;
 return runkey;
end $function$

CREATE OR REPLACE FUNCTION stock_v2.demo_return_spray(p_data jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'stock_v2'
AS $function$
declare v_job bigint; v_issue bigint; v_complete boolean; v_owner bigint; v_wh bigint; v_doc bigint; v_trace bigint; v_line jsonb; v_source bigint; v_qty numeric; v_issued numeric; v_returned numeric; v_item bigint; v_requirement bigint; v_num text; v_count int:=0;
begin
 perform pg_advisory_xact_lock(hashtext('stock_v2_inventory_posting'));
 v_job:=nullif(p_data->>'job_id','')::bigint;
 v_issue:=nullif(p_data->>'issue_document_id','')::bigint;
 v_complete:=coalesce((p_data->>'spray_complete')::boolean,false);
 if v_job is null or v_issue is null then raise exception 'Spray and original issue required';end if;
 if jsonb_typeof(p_data->'lines') is distinct from 'array' or jsonb_array_length(p_data->'lines') not between 1 and 30 then raise exception 'Choose return lines';end if;
 select owner_id into v_owner from stock_v2.owner where owner_code='TEST_JS';
 select location_id into v_wh from stock_v2.location where location_code='TEST_WH';
 select external_tracecode_id into v_trace from stock_v2.spray_job where job_id=v_job and owner_id=v_owner for update;
 if v_trace is null then raise exception 'Spray not found';end if; if not exists(select 1 from stock_v2.spray_job where job_id=v_job and status='completed') then raise exception 'Spray must be completed before returning stock';end if;
 if not exists(select 1 from stock_v2.document d join stock_v2.document_line dl on dl.document_id=d.document_id join stock_v2.spray_job_input ji on ji.requirement_id=dl.requirement_id where d.document_id=v_issue and d.document_type='issue' and d.status='posted' and ji.job_id=v_job) then raise exception 'Issue does not belong to the selected spray';end if;
 v_num:='SR-'||nextval('stock_v2.spray_return_number_seq');
 insert into stock_v2.document(document_type,document_number,document_date,status,parent_document_id,reason)
 values('return',v_num,current_date,'draft',v_issue,case when v_complete then 'Spray complete - unused stock returned' else 'Spray incomplete - unused stock returned' end) returning document_id into v_doc;
 for v_line in select value from jsonb_array_elements(p_data->'lines') loop
  v_source:=nullif(v_line->>'source_line_id','')::bigint;v_qty:=nullif(v_line->>'quantity','')::numeric;
  if v_qty is null or v_qty<=0 then raise exception 'Return quantities must be positive';end if;
  select dl.item_id,dl.requirement_id,dl.quantity into v_item,v_requirement,v_issued from stock_v2.document_line dl join stock_v2.spray_job_input ji on ji.requirement_id=dl.requirement_id
  where dl.line_id=v_source and dl.document_id=v_issue and ji.job_id=v_job;
  if v_item is null then raise exception 'Selected line does not belong to this issue';end if;
  select coalesce(sum(rl.quantity),0) into v_returned from stock_v2.document_line rl join stock_v2.document rd on rd.document_id=rl.document_id where rl.source_line_id=v_source and rd.document_type='return' and rd.status='posted';
  if v_qty>v_issued-v_returned then raise exception 'Return exceeds unreturned issue quantity';end if;
  insert into stock_v2.document_line(document_id,item_id,quantity,requirement_id,source_line_id,note)
  values(v_doc,v_item,v_qty,v_requirement,v_source,case when v_complete then 'Spray complete' else 'Spray incomplete' end);
  insert into stock_v2.movement(document_line_id,owner_id,location_id,quantity_delta,external_tracecode_id)
  values(currval(pg_get_serial_sequence('stock_v2.document_line','line_id')),v_owner,v_wh,v_qty,v_trace);
  v_count:=v_count+1;
 end loop;
 perform stock_v2.post_draft(v_doc);
 update stock_v2.spray_job set status=case when v_complete then 'completed' else 'planned' end where job_id=v_job;
 return jsonb_build_object('document_id',v_doc,'document_number',v_num,'job_id',v_job,'spray_complete',v_complete,'lines',v_count);
end $function$

CREATE OR REPLACE FUNCTION stock_v2.guard_document_changes()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'stock_v2'
AS $function$
begin
 if tg_op='DELETE' then
   if old.status='posted' then raise exception 'Posted documents cannot be deleted'; end if;
   return old;
 end if;
 if old.status='posted' then raise exception 'Posted documents cannot be edited; create a reversal'; end if;
 if old.status='void' then raise exception 'Voided documents cannot be edited'; end if;
 if new.status='posted' then
   if new.posted_at is null then raise exception 'posted_at must be provided'; end if;
   if not exists(select 1 from stock_v2.document_line where document_id=new.document_id) then raise exception 'Document has no lines'; end if;
   if exists (
     select 1 from stock_v2.document_line l
     left join lateral (
        select count(*) as ct,coalesce(sum(m.quantity_delta),0) as net,
               count(*) filter (where m.quantity_delta<0) as negatives,
               count(*) filter (where m.quantity_delta>0) as positives,
               count(distinct m.owner_id) as owners,
               count(distinct m.location_id) as locations
        from stock_v2.movement m where m.document_line_id=l.line_id
     ) x on true
     where l.document_id=new.document_id
       and (x.ct=0 or
           (new.document_type in ('grv','opening') and (x.negatives>0 or x.net<>l.quantity)) or
           (new.document_type='issue' and (x.positives>0 or x.net<>-l.quantity)) or (new.document_type='return' and ((exists(select 1 from stock_v2.supplier_return sr where sr.document_id=new.document_id) and (x.positives>0 or x.net<>-l.quantity)) or (not exists(select 1 from stock_v2.supplier_return sr where sr.document_id=new.document_id) and (x.negatives>0 or x.net<>l.quantity)))) or
           (new.document_type in ('ownership_transfer','location_transfer','reversal') and (x.ct<>2 or x.net<>0 or x.negatives<>1 or x.positives<>1)) or
           (new.document_type='ownership_transfer' and x.owners<>2) or
           (new.document_type='location_transfer' and x.locations<>2) or
           (new.document_type='adjustment' and (x.ct<>1 or abs(x.net)<>l.quantity))
       )
   ) then raise exception 'Invalid movement quantities for document %',new.document_id; end if;
 end if;
 return new;
end $function$

CREATE OR REPLACE FUNCTION stock_v2.guard_child_changes()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'stock_v2'
AS $function$
declare did bigint; st text;
begin
 if tg_table_name='document_line' then
   did:=case when tg_op='DELETE' then old.document_id else new.document_id end;
 else
   select document_id into did from stock_v2.document_line where line_id=(case when tg_op='DELETE' then old.document_line_id else new.document_line_id end);
 end if;
 select status into st from stock_v2.document where document_id=did for update;
 if st is distinct from 'draft' then raise exception 'Document lines and movements may only change while draft'; end if;
 if tg_op='UPDATE' then
   if tg_table_name='document_line' and old.document_id<>new.document_id then raise exception 'Cannot reparent document line'; end if;
   if tg_table_name='movement' and old.document_line_id<>new.document_line_id then raise exception 'Cannot reparent movement'; end if;
 end if;
 if tg_op='DELETE' then return old; else return new; end if;
end $function$

CREATE OR REPLACE FUNCTION stock_v2.check_grv_details()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'stock_v2'
AS $function$
begin
 if new.status='posted' and new.document_type='grv' then
   if not exists(select 1 from stock_v2.grv_detail where document_id=new.document_id) then
      raise exception 'GRV supplier and delivery note required';
   end if;
 end if;
 return new;
end $function$

CREATE OR REPLACE FUNCTION stock_v2.post_draft(p_document_id bigint)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'stock_v2'
AS $function$
declare d record; bad_count bigint;
begin
 select * into d from stock_v2.document where document_id=p_document_id for update;
 if not found or d.status<>'draft' then raise exception 'Only draft documents can be posted'; end if;
 -- In this private development schema, posting is restricted to database administrator;
 -- client roles have no schema access or EXECUTE grant.
 -- Serialize posting to avoid concurrent balance race conditions.
 perform pg_advisory_xact_lock(hashtext('stock_v2_inventory_posting'));
 -- lock and validate balances AFTER posting, protected by advisory lock.
 update stock_v2.document set status='posted', posted_at=clock_timestamp() where document_id=p_document_id;
 select count(*) into bad_count from (
   select m.owner_id,m.location_id,l.item_id
   from stock_v2.movement m join stock_v2.document_line l on l.line_id=m.document_line_id
   where l.document_id=p_document_id
   group by m.owner_id,m.location_id,l.item_id
 ) k where (
   select coalesce(sum(m2.quantity_delta),0)
   from stock_v2.movement m2 join stock_v2.document_line l2 on l2.line_id=m2.document_line_id
   join stock_v2.document d2 on d2.document_id=l2.document_id
   where d2.status='posted' and m2.owner_id=k.owner_id and m2.location_id=k.location_id and l2.item_id=k.item_id
 ) < 0;
 if bad_count>0 then raise exception 'Posting would create negative stock balance'; end if;
end $function$

CREATE OR REPLACE FUNCTION stock_v2.confirm_grv_price(p_line_id bigint, p_cost numeric, p_invoice text)
 RETURNS bigint
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'stock_v2'
AS $function$
declare doc record; oldrun bigint; newrun bigint; it bigint; previous numeric;
begin
 if p_cost is null or p_cost<0 or p_invoice is null or length(trim(p_invoice))=0 then raise exception 'Valid price and invoice required'; end if;
 select d.document_type,d.status,dl.item_id,gp.provisional_unit_cost
 into doc from stock_v2.document_line dl
 join stock_v2.document d on d.document_id=dl.document_id
 join stock_v2.grv_line_price gp on gp.line_id=dl.line_id
 where dl.line_id=p_line_id for update of dl;
 if not found or doc.document_type<>'grv' or doc.status<>'posted' then raise exception 'Posted GRV line required'; end if;
 if exists(select 1 from stock_v2.price_confirmation where line_id=p_line_id) then raise exception 'Price already confirmed'; end if;
 select run_id into oldrun from stock_v2.cost_run where status='complete' and run_id in
 (select run_id from stock_v2.cost_entry where item_id=doc.item_id) order by run_id desc limit 1;
 if oldrun is null then oldrun:=stock_v2.recalculate_costs('baseline before price confirmation',doc.item_id); end if;
 insert into stock_v2.price_confirmation(line_id,confirmed_unit_cost,invoice_number) values(p_line_id,p_cost,p_invoice);
 newrun:=stock_v2.recalculate_costs('invoice confirmation '||p_invoice,doc.item_id);
 insert into stock_v2.price_audit(line_id,previous_price,confirmed_price,invoice_number,old_run_id,new_run_id)
 values(p_line_id,doc.provisional_unit_cost,p_cost,p_invoice,oldrun,newrun);
 return newrun;
end $function$

CREATE OR REPLACE FUNCTION stock_v2.validate_ownership_transfer()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'stock_v2'
AS $function$
declare l record; neg record; pos record; c record; n integer;
begin
 if new.status <> 'posted' or new.document_type <> 'ownership_transfer' then return new; end if;
 for l in select * from stock_v2.document_line where document_id=new.document_id loop
   select count(*) into n from stock_v2.movement where document_line_id=l.line_id;
   if n<>2 then raise exception 'Ownership transfer requires exactly two movements for line %',l.line_id; end if;
   select * into neg from stock_v2.movement where document_line_id=l.line_id and quantity_delta<0;
   select * into pos from stock_v2.movement where document_line_id=l.line_id and quantity_delta>0;
   if neg.location_id<>pos.location_id then raise exception 'Ownership transfer must remain in same physical location'; end if;
   if -neg.quantity_delta<>l.quantity or pos.quantity_delta<>l.quantity then raise exception 'Transfer line must balance its stated quantity'; end if;
   select * into c from stock_v2.owner_charge where document_line_id=l.line_id;
   if not found or c.from_owner_id<>neg.owner_id or c.to_owner_id<>pos.owner_id or c.quantity<>l.quantity
   then raise exception 'Ownership transfer requires matching charge record for line %',l.line_id; end if;
 end loop;
 return new;
end $function$

CREATE OR REPLACE FUNCTION stock_v2.demo_workflow(p_action text, p_request uuid, p_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'stock_v2'
AS $function$
declare v_owner bigint;v_loc bigint;v_item bigint;v_id bigint;v_line bigint;v_doc bigint;v_order bigint;v_ol bigint;
 v_qty numeric;v_available numeric;v_code text;v_result jsonb;v_trace bigint;v_job bigint;v_area numeric;v_rate numeric;v_week date;v_req bigint;
begin
 if p_request is null or p_action not in ('order','grv','spray','planned_issue','direct_issue') then raise exception 'Invalid action';end if;
 perform pg_advisory_xact_lock(hashtext('stock_v2_inventory_posting'));
 select result into v_result from stock_v2.demo_workflow_requests where request_id=p_request;
 if found then return v_result||jsonb_build_object('replayed',true);end if;
 select owner_id into v_owner from stock_v2.owner where owner_code='TEST_JS';
 select location_id into v_loc from stock_v2.location where location_code='TEST_WH';
 if v_owner is null or v_loc is null then raise exception 'Demo owner or warehouse missing';end if;
 v_code:=p_payload->>'item_code';
 if v_code not in ('DEMO_MOSQUITO','DEMO_GLYPHOSATE','DEMO_LAMBDA','DEMO_COMPOUND_D') then raise exception 'Only demo products allowed';end if;
 select item_id into v_item from stock_v2.item where item_code=v_code and active=true;
 if v_item is null then raise exception 'Demo product missing';end if;
 if (p_payload->>'quantity') is not null then
  if (p_payload->>'quantity') !~ '^[0-9]+(\.[0-9]+)?$' then raise exception 'Invalid quantity';end if;
  v_qty:=(p_payload->>'quantity')::numeric;
  if v_qty<=0 or v_qty>100000 then raise exception 'Invalid quantity';end if;
 end if;
 if p_action='order' then
  if v_qty is null then raise exception 'Quantity required';end if;
  insert into stock_v2.order_header(order_number,owner_id,supplier_name,status,order_date)
  values('DEMO-PO-'||p_request::text,v_owner,coalesce(nullif(btrim(p_payload->>'supplier'),''),'DEMO Supplier'),'approved',current_date)
  returning order_id into v_order;
  insert into stock_v2.order_line(order_id,item_id,ordered_quantity,received_quantity)
  values(v_order,v_item,v_qty,0);
  update stock_v2.order_line set ordered_unit_price=nullif(p_payload->>'unit_price','')::numeric where order_id=v_order; v_result:=jsonb_build_object('order_id',v_order,'quantity',v_qty);
 elsif p_action='grv' then
  if v_qty is null then raise exception 'Quantity required';end if;
  if (p_payload->>'order_id') !~ '^[0-9]+$' then raise exception 'Order required';end if;
  v_order:=(p_payload->>'order_id')::bigint;
  select ol.order_line_id into v_ol from stock_v2.order_line ol join stock_v2.order_header h on h.order_id=ol.order_id
  where h.order_id=v_order and h.owner_id=v_owner and h.status='approved' and ol.item_id=v_item for update;
  if not found then raise exception 'Invalid DEMO purchase order or product';end if;
  if (select received_quantity+v_qty>ordered_quantity from stock_v2.order_line where order_line_id=v_ol) then raise exception 'GRV exceeds order balance';end if;
  insert into stock_v2.document(document_type,document_number,document_date,status,reason)
  values('grv','DEMO-GRV-'||p_request::text,current_date,'draft','DEMO GRV for PO '||v_order) returning document_id into v_doc;
  insert into stock_v2.document_line(document_id,item_id,quantity,note)
  values(v_doc,v_item,v_qty,'DEMO ordered stock received') returning line_id into v_line;
  insert into stock_v2.movement(document_line_id,owner_id,location_id,quantity_delta) values(v_line,v_owner,v_loc,v_qty);
  insert into stock_v2.grv_detail(document_id,supplier_name,delivery_note,price_status) values(v_doc,'DEMO Supplier','DEMO-DN-'||p_request::text,'pending');
  perform stock_v2.post_draft(v_doc);
  update stock_v2.order_line set received_quantity=received_quantity+v_qty where order_line_id=v_ol;
  insert into stock_v2.demo_grv_order_link(document_id,order_line_id,qty,received_unit_price) values(v_doc,v_ol,v_qty,nullif(p_payload->>'unit_price','')::numeric);
  v_result:=jsonb_build_object('document_id',v_doc,'order_id',v_order,'received',v_qty);
 elsif p_action='spray' then
  if (p_payload->>'tracecode_id') !~ '^[0-9]+$' or (p_payload->>'area_ha') !~ '^[0-9]+(\.[0-9]+)?$' or (p_payload->>'rate_per_ha') !~ '^[0-9]+(\.[0-9]+)?$' then raise exception 'Tracecode, area, rate required';end if;
  v_trace:=(p_payload->>'tracecode_id')::bigint;
  if not exists(select 1 from public.tracecode where tracecode_id=v_trace) then raise exception 'Tracecode not found';end if;
  v_area:=(p_payload->>'area_ha')::numeric;v_rate:=(p_payload->>'rate_per_ha')::numeric;
  if v_area<=0 or v_area>10000 or v_rate<=0 or v_rate>10000 then raise exception 'Invalid spray area or rate';end if;
  v_week:=stock_v2.week_start_for(current_date);
  insert into stock_v2.spray_job(external_tracecode_id,owner_id,planned_week_start,area_ha,spray_type,water_litres_per_ha,job_tracking_code)
  values(v_trace,v_owner,v_week,v_area,'DEMO Boom',coalesce(nullif(p_payload->>'water_rate','')::numeric,200),'DEMO') returning job_id into v_job;
  insert into stock_v2.spray_job_input(job_id,item_id,rate_per_ha) values(v_job,v_item,v_rate) returning requirement_id into v_req;
  -- trigger links requirement after insert, fetch persisted link
  select requirement_id into v_req from stock_v2.spray_job_input where job_id=v_job and item_id=v_item;
  v_result:=jsonb_build_object('job_id',v_job,'requirement_id',v_req,'planned_quantity',v_area*v_rate);
 elsif p_action='planned_issue' then
  if (p_payload->>'job_id') !~ '^[0-9]+$' then raise exception 'Spray job required';end if;
  v_job:=(p_payload->>'job_id')::bigint;
  select j.external_tracecode_id,ji.requirement_id,(ji.rate_per_ha*j.area_ha)
   into v_trace,v_req,v_available
  from stock_v2.spray_job j join stock_v2.spray_job_input ji on ji.job_id=j.job_id
  where j.job_id=v_job and j.owner_id=v_owner and j.status='planned' and ji.item_id=v_item for update of j;
  if not found then raise exception 'Outstanding demo spray input not found';end if;
  select coalesce(sum(dl.quantity),0) into v_rate from stock_v2.document_line dl join stock_v2.document d on d.document_id=dl.document_id
   where dl.requirement_id=v_req and d.document_type='issue' and d.status='posted';
  if v_qty is null then v_qty:=v_available-v_rate;end if;
  if v_qty<=0 or v_qty>v_available-v_rate then raise exception 'Issue exceeds outstanding planned quantity';end if;
 elsif p_action='direct_issue' then
  if v_qty is null or (p_payload->>'tracecode_id') !~ '^[0-9]+$' then raise exception 'Quantity and tracecode required';end if;
  v_trace:=(p_payload->>'tracecode_id')::bigint;
  if not exists(select 1 from public.tracecode where tracecode_id=v_trace) then raise exception 'Tracecode not found';end if;
 end if;
 if p_action in ('planned_issue','direct_issue') then
  select coalesce(sum(quantity),0) into v_available from stock_v2.quantity_balance where item_id=v_item and owner_id=v_owner and location_id=v_loc;
  if v_available<v_qty then raise exception 'Not enough TEST_JS stock: available %, requested %',v_available,v_qty;end if;
  insert into stock_v2.document(document_type,document_number,document_date,status,reason)
  values('issue','DEMO-ISS-'||p_request::text,current_date,'draft',p_action||' DEMO issue') returning document_id into v_doc;
  insert into stock_v2.document_line(document_id,item_id,quantity,requirement_id,note)
  values(v_doc,v_item,v_qty,v_req,'DEMO issue') returning line_id into v_line;
  insert into stock_v2.movement(document_line_id,owner_id,location_id,quantity_delta,external_tracecode_id)
  values(v_line,v_owner,v_loc,-v_qty,v_trace);
  perform stock_v2.post_draft(v_doc);
  if p_action='planned_issue' then
   update stock_v2.spray_job set status='completed'
   where job_id=v_job and not exists(
     select 1 from stock_v2.spray_job_input ji
     where ji.job_id=v_job and (ji.rate_per_ha*(select area_ha from stock_v2.spray_job where job_id=v_job))
     >coalesce((select sum(dl.quantity) from stock_v2.document_line dl join stock_v2.document d on d.document_id=dl.document_id
     where dl.requirement_id=ji.requirement_id and d.status='posted' and d.document_type='issue'),0)
   );
  end if;
  v_result:=jsonb_build_object('document_id',v_doc,'issued',v_qty,'job_id',v_job);
 end if;
 insert into stock_v2.demo_workflow_requests(request_id,action,result) values(p_request,p_action,v_result);
 return v_result;
end $function$

CREATE OR REPLACE FUNCTION stock_v2.admin_correct_quantity(p_line bigint, p_new_quantity numeric, p_reason text)
 RETURNS bigint
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'stock_v2'
AS $function$
declare src record; m record; previous_adjustment numeric; original_signed numeric; current_effect numeric; correction numeric; doc_id bigint; new_line_id bigint; no text;
begin
 perform pg_advisory_xact_lock(hashtext('stock_v2_inventory_posting'));
 if p_new_quantity is null or p_new_quantity<=0 then raise exception 'Corrected quantity must be positive'; end if;
 if length(trim(coalesce(p_reason,'')))<8 then raise exception 'Correction reason must be at least 8 characters'; end if;
 select d.document_id,d.document_type,d.document_date,l.line_id,l.item_id,l.quantity
 into src from stock_v2.document_line l join stock_v2.document d using(document_id)
 where l.line_id=p_line and d.status='posted';
 if not found or src.document_type not in ('issue','grv') then raise exception 'Only posted issue/GRV lines supported'; end if;
 select * into m from stock_v2.movement where document_line_id=p_line;
 if not found then raise exception 'Missing original movement'; end if;
 if (select count(*) from stock_v2.movement where document_line_id=p_line)<>1 then raise exception 'Split GRVs require separate correction process'; end if;
 select coalesce(sum(ma.quantity_delta),0) into previous_adjustment
 from stock_v2.document adj join stock_v2.document_line al on al.document_id=adj.document_id
 join stock_v2.movement ma on ma.document_line_id=al.line_id
 where adj.parent_document_id=src.document_id and adj.document_type='adjustment' and adj.status='posted' and al.source_line_id=p_line;
 original_signed:=case when src.document_type='issue' then -src.quantity else src.quantity end;
 current_effect:=original_signed+previous_adjustment;
 correction:=(case when src.document_type='issue' then -p_new_quantity else p_new_quantity end)-current_effect;
 if correction=0 then return null; end if;
 no:='ADMIN-CORR-'||nextval('stock_v2.admin_correction_number');
 insert into stock_v2.document(document_type,document_number,document_date,parent_document_id,reason)
 values('adjustment',no,current_date,src.document_id,p_reason) returning document_id into doc_id;
 insert into stock_v2.document_line(document_id,item_id,quantity,source_line_id,note)
 values(doc_id,src.item_id,abs(correction),p_line,'Admin quantity correction') returning line_id into new_line_id;
 insert into stock_v2.movement(document_line_id,owner_id,location_id,quantity_delta,external_tracecode_id)
 values(new_line_id,m.owner_id,m.location_id,correction,m.external_tracecode_id);
 perform stock_v2.post_draft(doc_id);
 return doc_id;
end $function$

CREATE OR REPLACE FUNCTION stock_v2.admin_reverse_simple(p_document_id bigint, p_reason text)
 RETURNS bigint
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'stock_v2'
AS $function$
declare src record; r record; new_doc bigint; new_line bigint; ref text;
begin
 perform pg_advisory_xact_lock(hashtext('stock_v2_inventory_posting'));
 if length(trim(coalesce(p_reason,'')))<8 then raise exception 'Reversal reason must be at least 8 characters'; end if;
 select * into src from stock_v2.document where document_id=p_document_id and status='posted' for update;
 if not found or src.document_type not in ('grv','issue') then raise exception 'Only simple posted GRVs or issues may be reversed'; end if;
 if exists(select 1 from stock_v2.document_line l join stock_v2.movement m on m.document_line_id=l.line_id
 where l.document_id=p_document_id group by l.line_id having count(*)<>1) then raise exception 'Split lines cannot use simple reversal'; end if;
 if exists(select 1 from stock_v2.document_line l join stock_v2.document_line later on later.source_line_id=l.line_id
 join stock_v2.document d on d.document_id=later.document_id
 where l.document_id=p_document_id and d.status='posted') then raise exception 'Document has dependent returns or corrections'; end if;
 if exists(select 1 from stock_v2.document where parent_document_id=p_document_id and document_type='adjustment' and status='posted') then raise exception 'Document already corrected'; end if;
 if exists(select 1 from stock_v2.document where parent_document_id=p_document_id and reason like 'ADMIN REVERSAL:%' and status='posted') then raise exception 'Document already reversed'; end if;
 ref:='ADMIN-REV-'||nextval('stock_v2.admin_correction_number');
 insert into stock_v2.document(document_type,document_number,document_date,parent_document_id,reason)
 values('adjustment',ref,current_date,p_document_id,'ADMIN REVERSAL: '||p_reason) returning document_id into new_doc;
 for r in select dl.line_id,dl.item_id,dl.quantity,m.owner_id,m.location_id,m.quantity_delta,m.external_tracecode_id
 from stock_v2.document_line dl join stock_v2.movement m on m.document_line_id=dl.line_id
 where dl.document_id=p_document_id loop
   insert into stock_v2.document_line(document_id,item_id,quantity,source_line_id,note)
   values(new_doc,r.item_id,r.quantity,r.line_id,'Full reversal') returning line_id into new_line;
   insert into stock_v2.movement(document_line_id,owner_id,location_id,quantity_delta,external_tracecode_id)
   values(new_line,r.owner_id,r.location_id,-r.quantity_delta,r.external_tracecode_id);
 end loop;
 perform stock_v2.post_draft(new_doc);
 return new_doc;
end $function$

CREATE OR REPLACE FUNCTION stock_v2.recalculate_costs(p_reason text, p_item_id bigint)
 RETURNS bigint
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'stock_v2'
AS $function$
declare r record; q numeric(20,6); v numeric(26,8); avg_cost numeric(26,10);
 unit_price numeric(20,8); mv numeric(26,8); provisional_flag boolean; runkey bigint;
begin
 perform pg_advisory_xact_lock(hashtext('stock_v2_inventory_posting'));
 if exists(
  select 1 from stock_v2.document d join stock_v2.document_line dl on dl.document_id=d.document_id
  where d.status='posted' and dl.item_id=p_item_id
  and d.document_type not in ('opening','grv','issue','return')
 ) then raise exception 'Unsupported posted movement type for costing replay'; end if;
 if exists(
  select 1 from stock_v2.movement m join stock_v2.document_line dl on dl.line_id=m.document_line_id
  join stock_v2.document d on d.document_id=dl.document_id where d.status='posted' and dl.item_id=p_item_id and
  d.document_type='return' and dl.source_line_id is null
 ) then raise exception 'Returns must reference original issue lines for costing'; end if;
 insert into stock_v2.cost_run(reason) values(p_reason) returning run_id into runkey;
 for r in
 select m.movement_id,m.quantity_delta,m.owner_id,
 dl.item_id,dl.line_id,dl.source_line_id,d.document_type,d.document_date,d.document_id,
 coalesce(pc.confirmed_unit_cost,gp.actual_unit_cost) as actual_unit_cost,gp.provisional_unit_cost
 from stock_v2.movement m join stock_v2.document_line dl on dl.line_id=m.document_line_id
 join stock_v2.document d on d.document_id=dl.document_id
 left join stock_v2.grv_line_price gp on gp.line_id=dl.line_id left join stock_v2.price_confirmation pc on pc.line_id=dl.line_id
 where d.status='posted' and dl.item_id=p_item_id
 order by m.owner_id,d.document_date,d.document_id,m.movement_id
 loop
 select coalesce(sum(ce.movement_value),0),coalesce(sum(m2.quantity_delta),0)
 into v,q from stock_v2.cost_entry ce
 join stock_v2.movement m2 on m2.movement_id=ce.movement_id
 where ce.run_id=runkey and ce.item_id=r.item_id and ce.owner_id=r.owner_id;
 avg_cost:=case when q>0 then v/q else null end;
 provisional_flag:=false;
 if r.document_type in ('opening','grv') then
   unit_price:=coalesce(r.actual_unit_cost,r.provisional_unit_cost,avg_cost);
   if unit_price is null then raise exception 'Opening/GRV price missing with no existing WA for line %',r.line_id; end if;
   provisional_flag:=r.actual_unit_cost is null;
   mv:=r.quantity_delta*unit_price;
 elsif r.document_type='return' then
   select ce.movement_value/m2.quantity_delta into unit_price
   from stock_v2.cost_entry ce join stock_v2.movement m2 on m2.movement_id=ce.movement_id
   join stock_v2.document_line l2 on l2.line_id=m2.document_line_id
   where ce.run_id=runkey and l2.line_id=r.source_line_id and m2.owner_id=r.owner_id
   order by ce.movement_id limit 1;
   if unit_price is null then raise exception 'Original issue not costed for return line %',r.line_id; end if;
   mv:=r.quantity_delta*unit_price;
 else
   if avg_cost is null then raise exception 'No weighted average for issue line %',r.line_id; end if;
   mv:=r.quantity_delta*avg_cost;
 end if;
 if q+r.quantity_delta < 0 then raise exception 'Cost replay negative stock at line %',r.line_id; end if;
 insert into stock_v2.cost_entry(run_id,movement_id,item_id,owner_id,quantity_after,value_after,unit_cost,movement_value,provisional)
 values(runkey,r.movement_id,r.item_id,r.owner_id,q+r.quantity_delta,v+mv,
 case when q+r.quantity_delta>0 then (v+mv)/(q+r.quantity_delta) else 0 end,mv,provisional_flag);
 end loop;
 update stock_v2.cost_run set status='complete',finished_at=now() where run_id=runkey;
 return runkey;
end $function$

CREATE OR REPLACE FUNCTION stock_v2.value_transfer_charges(p_run_id bigint)
 RETURNS integer
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'stock_v2'
AS $function$
declare n integer;
begin
 perform pg_advisory_xact_lock(hashtext('stock_v2_inventory_posting'));
 if not exists (select 1 from stock_v2.cost_run where run_id=p_run_id and status='complete') then
   raise exception 'Completed costing run required';
 end if;
 if exists (select 1 from stock_v2.charge_valuation where run_id=p_run_id) then
   raise exception 'Run has already had charges valued';
 end if;
 insert into stock_v2.charge_valuation(run_id,charge_id,inventory_transfer_value)
 select p_run_id,c.charge_id, -sum(ce.movement_value)
 from stock_v2.owner_charge c
 join stock_v2.document_line dl on dl.line_id=c.document_line_id
 join stock_v2.document d on d.document_id=dl.document_id
 join stock_v2.movement m on m.document_line_id=dl.line_id and m.owner_id=c.from_owner_id and m.quantity_delta<0
 join stock_v2.cost_entry ce on ce.movement_id=m.movement_id and ce.run_id=p_run_id
 where d.status='posted' and d.document_type='ownership_transfer'
 group by c.charge_id;
 get diagnostics n=row_count;
 return n;
end $function$

CREATE OR REPLACE FUNCTION stock_v2.validate_admin_adjustment()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'stock_v2'
AS $function$
declare parent_type text; parent_line bigint; parent_item bigint; parent_owner bigint; parent_location bigint; parent_trace bigint; r record;
begin
 if new.status<>'posted' or new.document_type<>'adjustment' or new.parent_document_id is null then return new; end if;
 select document_type into parent_type from stock_v2.document where document_id=new.parent_document_id and status='posted';
 if parent_type not in ('issue','grv') then raise exception 'Adjustment must reference posted issue or GRV'; end if;
 if not exists(select 1 from stock_v2.document_line where document_id=new.document_id) then raise exception 'Empty correction'; end if;
 for r in select dl.*,m.owner_id,m.location_id,m.quantity_delta,m.external_tracecode_id
 from stock_v2.document_line dl join stock_v2.movement m on m.document_line_id=dl.line_id
 where dl.document_id=new.document_id loop
  if r.source_line_id is null then raise exception 'Correction line must identify original line'; end if;
  select item_id into parent_item from stock_v2.document_line where line_id=r.source_line_id and document_id=new.parent_document_id;
  if not found or r.item_id<>parent_item then raise exception 'Correction input mismatch'; end if;
  select owner_id,location_id,external_tracecode_id into parent_owner,parent_location,parent_trace from stock_v2.movement where document_line_id=r.source_line_id;
  if r.owner_id<>parent_owner or r.location_id<>parent_location or r.external_tracecode_id is distinct from parent_trace then raise exception 'Correction ownership/location/tracecode mismatch'; end if;
  if parent_type='issue' and r.external_tracecode_id is null then raise exception 'Issue correction must identify tracecode'; end if;
 end loop;
 if new.reason is null or length(trim(new.reason))<8 then raise exception 'Correction reason required'; end if;
 return new;
end $function$

CREATE OR REPLACE FUNCTION stock_v2.recalculate_transfer_costs(p_item_id bigint, p_reason text)
 RETURNS bigint
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'stock_v2'
AS $function$
declare r record; runkey bigint; q numeric; v numeric; uc numeric; delta_value numeric; partner_value numeric; src_move bigint; source_type text;
begin
 perform pg_advisory_xact_lock(hashtext('stock_v2_inventory_posting'));
 if exists(select 1 from stock_v2.document_line l join stock_v2.document d using(document_id)
 where l.item_id=p_item_id and d.status='posted' and d.document_type not in ('opening','grv','issue','return','ownership_transfer','adjustment'))
 then raise exception 'Unsupported document type in costing replay'; end if;
 insert into stock_v2.cost_run(reason) values(p_reason) returning run_id into runkey;
 for r in
 select m.*,l.item_id,l.source_line_id,d.document_type,d.document_id,d.document_date,
 coalesce(pc.confirmed_unit_cost,gp.actual_unit_cost) as confirmed_price,gp.provisional_unit_cost
 from stock_v2.document d join stock_v2.document_line l using(document_id)
 join stock_v2.movement m on m.document_line_id=l.line_id
 left join stock_v2.grv_line_price gp on gp.line_id=l.line_id
 left join stock_v2.price_confirmation pc on pc.line_id=l.line_id
 where d.status='posted' and l.item_id=p_item_id
 order by d.document_date,d.document_id,
 case when d.document_type='ownership_transfer' and m.quantity_delta<0 then 0 else 1 end,
 m.movement_id
 loop
 select coalesce(sum(e.movement_value),0),coalesce(sum(mm.quantity_delta),0) into v,q
 from stock_v2.cost_entry e join stock_v2.movement mm using(movement_id)
 where e.run_id=runkey and e.item_id=p_item_id and e.owner_id=r.owner_id;
 uc:=case when q>0 then v/q else null end;
 if r.document_type in ('opening','grv') then
   uc:=coalesce(r.confirmed_price,r.provisional_unit_cost,uc);
   if uc is null then raise exception 'Missing opening WA price on line %',r.document_line_id; end if;
   delta_value:=r.quantity_delta*uc;
 elsif r.document_type='ownership_transfer' and r.quantity_delta>0 then
   select e.movement_value,m2.movement_id into partner_value,src_move
   from stock_v2.cost_entry e join stock_v2.movement m2 using(movement_id)
   where e.run_id=runkey and m2.document_line_id=r.document_line_id and m2.quantity_delta<0
   limit 1;
   if src_move is null then raise exception 'Transfer outgoing cost not found'; end if;
   delta_value:=-partner_value;
 elsif r.document_type='adjustment' then
   if r.source_line_id is null then raise exception 'Unlinked adjustment unsupported'; end if;
   select source_doc.document_type into strict source_type
   from stock_v2.document_line sl join stock_v2.document source_doc on source_doc.document_id=sl.document_id
   where sl.line_id=r.source_line_id;
   if source_type not in ('issue','grv') then raise exception 'Unsupported adjustment source'; end if;
   if source_type='grv' then
     select coalesce(pc.confirmed_unit_cost,gp.actual_unit_cost,gp.provisional_unit_cost)
     into uc from stock_v2.grv_line_price gp left join stock_v2.price_confirmation pc using(line_id)
     where gp.line_id=r.source_line_id;
     uc:=coalesce(uc,case when q>0 then v/q else null end);
   end if;
   if uc is null then raise exception 'Missing WA for correction'; end if;
   delta_value:=r.quantity_delta*uc;
 elsif r.document_type='return' then
   select e.movement_value/mm.quantity_delta into uc
   from stock_v2.cost_entry e join stock_v2.movement mm using(movement_id)
   where e.run_id=runkey and mm.document_line_id=r.source_line_id and mm.owner_id=r.owner_id
     and mm.quantity_delta<0 limit 1;
   if uc is null then raise exception 'Return without priced original issue'; end if;
   delta_value:=r.quantity_delta*uc;
 else
   if uc is null then raise exception 'Issue/transfer without stock WA'; end if;
   delta_value:=r.quantity_delta*uc;
 end if;
 if q+r.quantity_delta<0 then raise exception 'Negative stock replay for owner %, item %',r.owner_id,p_item_id; end if;
 insert into stock_v2.cost_entry(run_id,movement_id,item_id,owner_id,quantity_after,value_after,unit_cost,movement_value,provisional)
 values(runkey,r.movement_id,p_item_id,r.owner_id,q+r.quantity_delta,v+delta_value,
 case when q+r.quantity_delta>0 then (v+delta_value)/(q+r.quantity_delta) else 0 end,
 delta_value,r.document_type in ('grv','opening') and r.confirmed_price is null);
 end loop;
 update stock_v2.cost_run set status='complete',finished_at=now() where run_id=runkey;
 return runkey;
end $function$

CREATE OR REPLACE FUNCTION stock_v2.sync_verified_spray_requirements()
 RETURNS integer
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'stock_v2'
AS $function$
declare n integer;
begin
 if exists(select 1 from stock_v2.spray_requirement_preview where mapping_status<>'ready') then
   raise exception 'Unverified spray tracecode ownership, unmapped inputs, or invalid area/rate. Review spray_requirement_preview';
 end if;
 insert into stock_v2.requirement(owner_id,external_tracecode_id,item_id,planned_quantity,required_date,source_kind,source_key,reference,status)
 select owner_id,external_tracecode_id,item_id,required_quantity,
 null::date,'spray','public_spray:'||spray_id,'Public spray #'||spray_id,'active'
 from stock_v2.spray_requirement_preview
 on conflict (source_kind,source_key) where source_key is not null
 do update set owner_id=excluded.owner_id,external_tracecode_id=excluded.external_tracecode_id,
 item_id=excluded.item_id,planned_quantity=excluded.planned_quantity,required_date=excluded.required_date,status='active';
 get diagnostics n=row_count;
 return n;
end $function$

CREATE OR REPLACE FUNCTION stock_v2.sync_spray_job_requirement()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'stock_v2'
AS $function$
declare j record; req bigint; keytext text;
begin
 select * into j from stock_v2.spray_job where job_id=new.job_id;
 if j.status <> 'planned' then raise exception 'Only planned spray jobs accept inputs'; end if;
 keytext:='spray_job_input:'||new.job_input_id;
 insert into stock_v2.requirement(owner_id,external_tracecode_id,item_id,planned_quantity,required_date,source_kind,source_key,reference,status)
 values(j.owner_id,j.external_tracecode_id,new.item_id,new.rate_per_ha*j.area_ha,j.planned_week_start,'spray',keytext,'Spray job '||j.job_id,'active')
 on conflict (source_kind,source_key) where source_key is not null
 do update set owner_id=excluded.owner_id,external_tracecode_id=excluded.external_tracecode_id,
 item_id=excluded.item_id,planned_quantity=excluded.planned_quantity,required_date=excluded.required_date,status='active'
 returning requirement_id into req;
 update stock_v2.spray_job_input set requirement_id=req where job_input_id=new.job_input_id and requirement_id is distinct from req;
 return null;
end $function$

CREATE OR REPLACE FUNCTION stock_v2.demo_multi(p_action text, p_request uuid, p_data jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'stock_v2'
AS $function$
declare own bigint;loc bigint;doc bigint;ord bigint;job bigint;ln bigint;it bigint;ol bigint;req bigint;tr bigint;contract bigint;targetown bigint;qty numeric;rate numeric;area numeric;old_qty numeric;avail numeric;el jsonb;code text;res jsonb;arr jsonb:='[]'::jsonb;ct int:=0; recost_item bigint; cost_run_id bigint; cost_runs jsonb:='[]'::jsonb; cost_pending jsonb:='[]'::jsonb;
begin
 if p_action not in ('order','grv','direct_grv','spray','planned_issue','direct_issue','ownership_transfer') or p_request is null then raise exception 'Invalid operation';end if;
 if jsonb_typeof(p_data->'lines') is distinct from 'array' then raise exception 'Product lines are required';end if;
  if jsonb_array_length(p_data->'lines') not between 1 and 30 then raise exception 'Provide 1-30 product lines';end if;
 perform pg_advisory_xact_lock(hashtext('stock_v2_inventory_posting'));
 select result into res from stock_v2.demo_workflow_requests where request_id=p_request; if found then return res||jsonb_build_object('replayed',true);end if;
 select owner_id into own from stock_v2.owner where owner_code='TEST_'||coalesce(nullif(p_data->>'owner_code',''),'JS') and active;
 if own is null then raise exception 'Unknown test stock owner';end if;
 if p_action in ('grv','direct_grv') then
  if coalesce(p_data->>'receipt_mode','') not in ('dnote','invoice') then raise exception 'Choose DNote or Invoice GRV';end if;
  if p_data->>'receipt_mode'='dnote' and nullif(btrim(p_data->>'delivery_note'),'') is null then raise exception 'Delivery Note Number required';end if;
  if p_data->>'receipt_mode'='invoice' and nullif(btrim(p_data->>'invoice_number'),'') is null then raise exception 'Supplier Invoice Number required';end if;
  if p_data->>'receipt_mode'='invoice' and exists(select 1 from jsonb_array_elements(p_data->'lines') x where nullif(x->>'unit_price','') is null or (x->>'unit_price')::numeric<=0) then raise exception 'Invoice GRVs require positive unit prices for every line';end if;
  if nullif(p_data->>'receipt_date','') is null then raise exception 'Receipt date required';end if;
 end if;
 if p_action='direct_grv' and not exists(select 1 from stock_v2.owner_policy where owner_id=own and allow_direct_grv) then raise exception 'This stock owner requires a PO-linked GRV';end if;
 if p_action in ('spray','planned_issue','direct_issue') and own<>(select owner_id from stock_v2.owner where owner_code='TEST_JS') then raise exception 'Only JS demo issues currently enabled';end if;
 if p_action='ownership_transfer' then
  select owner_id into targetown from stock_v2.owner where owner_code='TEST_'||coalesce(nullif(p_data->>'to_owner_code',''),'') and active;
  if targetown is null or targetown=own then raise exception 'Choose another active test stock owner';end if;
 end if;
 if p_action in ('order','direct_grv') then
  select default_contract_id into contract from stock_v2.owner_policy where owner_id=own;
  if contract is null then contract:=nullif(p_data->>'contract_id','')::bigint;end if;
 end if;
 select location_id into loc from stock_v2.location where location_code='TEST_WH';
 if p_action in ('spray','planned_issue','direct_issue') then
  tr:=nullif(p_data->>'tracecode_id','')::bigint;
  if p_action='planned_issue' then
   job:=(p_data->>'job_id')::bigint;
   select external_tracecode_id into tr from stock_v2.spray_job where job_id=job and owner_id=own and status='planned';
  end if;
  if tr is null or not exists(select 1 from public.tracecode where tracecode_id=tr) then raise exception 'Valid tracecode required';end if;
 end if;
 if p_action='order' then
  insert into stock_v2.order_header(order_number,owner_id,supplier_name,status,order_date)
  values('DEMO-PO-'||p_request,own,coalesce(nullif(p_data->>'supplier',''),'DEMO Supplier'),'approved',coalesce(nullif(p_data->>'order_date','')::date,current_date)) returning order_id into ord;
  if exists(select 1 from stock_v2.owner_policy where owner_id=own and po_requires_contract) and (contract is null or not exists(select 1 from stock_v2.contracts where contract_id=contract and active)) then raise exception 'Active contract required';end if;
  update stock_v2.order_header set contract_id=contract where order_id=ord;
 elsif p_action='grv' then
  ord:=(p_data->>'order_id')::bigint;
  if not exists(select 1 from stock_v2.order_header where order_id=ord and owner_id=own and status='approved') then raise exception 'Outstanding test order required';end if;
  select contract_id into contract from stock_v2.order_header where order_id=ord;
  -- Older demo POs may predate contract assignment. Keep those receivable; new orders require contracts according to owner policy.
  insert into stock_v2.document(document_type,document_number,document_date,status,reason)
  values('grv','DEMO-GRV-'||p_request,(p_data->>'receipt_date')::date,'draft','Test GRV against order '||ord) returning document_id into doc;
  insert into stock_v2.grv_detail(document_id,supplier_name,delivery_note,price_status)
  select doc,supplier_name,coalesce(nullif(p_data->>'delivery_note',''),'DEMO-DN-'||p_request),'pending'
  from stock_v2.order_header where order_id=ord;
  update stock_v2.document set contract_id=contract where document_id=doc;
  update stock_v2.grv_detail set invoice_number=nullif(p_data->>'invoice_number',''),
    delivery_note_date=case when p_data->>'receipt_mode'='dnote' then (p_data->>'receipt_date')::date else null end,
    invoice_date=case when p_data->>'receipt_mode'='invoice' then (p_data->>'receipt_date')::date else null end,
    price_status=case when p_data->>'receipt_mode'='invoice' then 'confirmed' else 'pending' end where document_id=doc;
 elsif p_action='direct_grv' then
  insert into stock_v2.document(document_type,document_number,document_date,status,reason,contract_id)
  values('grv','DEMO-DIRECT-GRV-'||p_request,(p_data->>'receipt_date')::date,'draft','Direct GRV',contract) returning document_id into doc;
  insert into stock_v2.grv_detail(document_id,supplier_name,delivery_note,price_status)
  values(doc,coalesce(nullif(p_data->>'supplier',''),'Direct supplier'),coalesce(nullif(p_data->>'delivery_note',''),'DEMO-DIRECT-'||p_request),case when p_data->>'receipt_mode'='invoice' then 'confirmed' else 'pending' end);
  update stock_v2.grv_detail set invoice_number=nullif(p_data->>'invoice_number',''),
    delivery_note_date=case when p_data->>'receipt_mode'='dnote' then (p_data->>'receipt_date')::date else null end,
    invoice_date=case when p_data->>'receipt_mode'='invoice' then (p_data->>'receipt_date')::date else null end where document_id=doc;
 elsif p_action='ownership_transfer' then
  insert into stock_v2.document(document_type,document_number,document_date,status,reason)
  values('ownership_transfer','DEMO-TR-'||p_request,current_date,'draft',coalesce(p_data->>'owner_code','')||' to '||coalesce(p_data->>'to_owner_code','')) returning document_id into doc;
 elsif p_action='spray' then
  area:=(p_data->>'area_ha')::numeric;
  if (p_data->>'part_label') is null then raise exception 'Part required'; end if;
  if (p_data->>'spray_type') is null then raise exception 'Spray Type required'; end if;
  if not exists(select 1 from stock_v2.access_spray_type_catalog where spray_type_name=p_data->>'spray_type') then raise exception 'Unknown spray type'; end if;
  if area > (select tracecode_size from public.tracecode where tracecode_id=tr) then raise exception 'Spray part area exceeds tracecode hectares';end if;
  if area<=0 or area>10000 then raise exception 'Invalid area';end if;
  insert into stock_v2.spray_job(external_tracecode_id,owner_id,planned_week_start,area_ha,spray_type,job_tracking_code,water_litres_per_ha)
  values(tr,own,coalesce(nullif(p_data->>'planned_week_start','')::date,date_trunc('week',current_date)::date),area,coalesce(p_data->>'spray_type','DEMO Boom'),'DEMO',coalesce((p_data->>'water_rate')::numeric,200))
  returning job_id into job;
  update stock_v2.spray_job set sprayer_asset_code=nullif(p_data->>'sprayer_asset_code',''),part_label=nullif(p_data->>'part_label',''),
  setup_id=(select setup_id from stock_v2.sprayer_setup where setup_name=p_data->>'spray_type' and active=true limit 1)
  where job_id=job;
 elsif p_action in ('planned_issue','direct_issue') then
  insert into stock_v2.document(document_type,document_number,document_date,status,reason)
  values('issue','DEMO-ISS-'||p_request,current_date,'draft',p_action) returning document_id into doc;
 end if;
 for el in select value from jsonb_array_elements(p_data->'lines') loop
  code:=el->>'item_code';
  if code is null or length(code)=0 then raise exception 'Product code required';end if;
  if exists(select 1 from jsonb_array_elements(arr) x where x->>'item_code'=code) then raise exception 'Duplicate product %',code;end if;
  select item_id into it from stock_v2.item where item_code=code and active=true;
  if it is null then raise exception 'Product unavailable';end if;
  if p_action='spray' then
   rate:=(el->>'rate_per_ha')::numeric;
   if rate<=0 or rate>10000 then raise exception 'Invalid rate for %',code;end if;
   insert into stock_v2.spray_job_input(job_id,item_id,rate_per_ha) values(job,it,rate);
   qty:=rate*area;
  else
   qty:=(el->>'quantity')::numeric;
   if qty<=0 or qty>100000 then raise exception 'Invalid quantity for %',code;end if;
  end if;
  if p_action='order' then
   insert into stock_v2.order_line(order_id,item_id,ordered_quantity,received_quantity,ordered_unit_price)
   values(ord,it,qty,0,(el->>'unit_price')::numeric);
  elsif p_action='direct_grv' then
   insert into stock_v2.document_line(document_id,item_id,quantity,note) values(doc,it,qty,'Direct GRV') returning line_id into ln;
   insert into stock_v2.movement(document_line_id,owner_id,location_id,quantity_delta) values(ln,own,loc,qty);
   insert into stock_v2.grv_line_price(line_id,actual_unit_cost) values(ln,
      case when p_data->>'receipt_mode'='invoice' then (el->>'unit_price')::numeric else null end);
  elsif p_action='ownership_transfer' then
   if coalesce((select sum(quantity_delta) from stock_v2.movement m join stock_v2.document_line d on d.line_id=m.document_line_id where m.owner_id=own and m.location_id=loc and d.item_id=it),0)<qty then raise exception 'Insufficient source owner stock for %',code;end if;
   insert into stock_v2.document_line(document_id,item_id,quantity,note) values(doc,it,qty,'JS/AO ownership transfer') returning line_id into ln;
   insert into stock_v2.movement(document_line_id,owner_id,location_id,quantity_delta) values(ln,own,loc,-qty);
   insert into stock_v2.movement(document_line_id,owner_id,location_id,quantity_delta) values(ln,targetown,loc,qty);
   insert into stock_v2.owner_charge(document_line_id,from_owner_id,to_owner_id,quantity,charge_status,valuation_amount)
   values(ln,own,targetown,qty,'unpriced',null);
  elsif p_action='grv' then
   select order_line_id,ordered_quantity-received_quantity into ol,avail
   from stock_v2.order_line where order_id=ord and item_id=it for update;
   if ol is null or qty>avail then raise exception 'Quantity exceeds outstanding order for %',code;end if;
   insert into stock_v2.document_line(document_id,item_id,quantity,note) values(doc,it,qty,'Test GRV') returning line_id into ln;
   insert into stock_v2.movement(document_line_id,owner_id,location_id,quantity_delta) values(ln,own,loc,qty);
   update stock_v2.order_line set received_quantity=received_quantity+qty where order_line_id=ol;
   insert into stock_v2.demo_grv_line_link(document_id,order_line_id,qty,received_unit_price)
   values(doc,ol,qty,case when p_data->>'receipt_mode'='invoice' then (el->>'unit_price')::numeric else null end);
   insert into stock_v2.grv_line_price(line_id,actual_unit_cost) values(ln,
      case when p_data->>'receipt_mode'='invoice' then (el->>'unit_price')::numeric else null end);
  elsif p_action in ('planned_issue','direct_issue') then
   if p_action='planned_issue' then
    select ji.requirement_id,ji.rate_per_ha*j.area_ha into req,avail from stock_v2.spray_job_input ji
    join stock_v2.spray_job j on j.job_id=ji.job_id where j.job_id=job and ji.item_id=it;
    if req is null then raise exception 'Product % not in spray programme',code;end if;
    select coalesce(sum(case when d.document_type='issue' then dl.quantity when d.document_type='return' then -dl.quantity else 0 end),0) into old_qty from stock_v2.document_line dl join stock_v2.document d on d.document_id=dl.document_id
    where dl.requirement_id=req and d.status='posted' and d.document_type in ('issue','return');
    if qty>avail-old_qty then raise exception 'Issue exceeds outstanding spray quantity for %',code;end if;
   else req:=null;end if;
   insert into stock_v2.document_line(document_id,item_id,quantity,requirement_id,note) values(doc,it,qty,req,case when p_action='direct_issue' then nullif(el->>'mix_instruction','') else 'DEMO issue' end) returning line_id into ln;
   insert into stock_v2.movement(document_line_id,owner_id,location_id,quantity_delta,external_tracecode_id) values(ln,own,loc,-qty,tr);
  end if;
  arr:=arr||jsonb_build_array(jsonb_build_object('item_code',code,'quantity',qty));ct:=ct+1;
 end loop;
 if ct=0 then raise exception 'Cannot post an empty document';end if;
 if doc is not null then perform stock_v2.post_draft(doc);end if;
 if p_action='planned_issue' then
 update stock_v2.spray_job set status='completed' where job_id=job and not exists(
  select 1 from stock_v2.spray_job_input ji where ji.job_id=job and ji.rate_per_ha*(select area_ha from stock_v2.spray_job where job_id=job)>
  coalesce((select sum(case when d.document_type='issue' then dl.quantity when d.document_type='return' then -dl.quantity else 0 end) from stock_v2.document_line dl join stock_v2.document d on d.document_id=dl.document_id
   where dl.requirement_id=ji.requirement_id and d.status='posted' and d.document_type in ('issue','return')),0));
 end if;
 if p_action in ('grv','direct_grv') and p_data->>'receipt_mode'='invoice' then
  for recost_item in select distinct item_id from stock_v2.document_line where document_id=doc loop
    begin
      cost_run_id:=stock_v2.recalculate_demo_item_costs(recost_item,'Invoice '||(p_data->>'invoice_number')||' GRV '||doc);
      cost_runs:=cost_runs||jsonb_build_array(jsonb_build_object('item_id',recost_item,'run_id',cost_run_id));
    exception when others then
      cost_pending:=cost_pending||jsonb_build_array(jsonb_build_object('item_id',recost_item,'reason',sqlerrm));
    end;
  end loop;
 end if;
 res:=jsonb_build_object('order_id',ord,'document_id',doc,'job_id',job,'lines',arr,'cost_runs',cost_runs,'cost_pending',cost_pending);
 insert into stock_v2.demo_workflow_requests(request_id,action,result) values(p_request,p_action,res);
 return res;
end $function$

CREATE OR REPLACE FUNCTION stock_v2.demo_direct_issue(p_request_id uuid, p_tracecode_id bigint, p_purpose text, p_lines jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'stock_v2'
AS $function$
declare v_owner bigint;v_loc bigint;v_doc bigint;v_line bigint;v_item bigint;
v_el jsonb;v_qty numeric;v_code text;v_before numeric;v_after numeric;v_result jsonb:='[]'::jsonb;
begin
 if p_request_id is null or p_purpose is null or length(btrim(p_purpose))<3 or length(p_purpose)>300 then raise exception 'Purpose is required'; end if;
 if not exists(select 1 from public.tracecode where tracecode_id=p_tracecode_id) then raise exception 'Unknown tracecode'; end if;
 if jsonb_typeof(p_lines)<>'array' or jsonb_array_length(p_lines)<1 or jsonb_array_length(p_lines)>15 then raise exception 'Specify 1-15 demo products'; end if;
 perform pg_advisory_xact_lock(hashtext('stock_v2_inventory_posting'));
 select document_id into v_doc from stock_v2.demo_issue_request where request_id=p_request_id;
 if v_doc is not null then return jsonb_build_object('document_id',v_doc,'duplicate',true);end if;
 select owner_id into v_owner from stock_v2.owner where owner_code='TEST_JS';
 select location_id into v_loc from stock_v2.location where location_code='TEST_WH';
 if v_owner is null or v_loc is null then raise exception 'Missing test stock setup';end if;
 insert into stock_v2.document(document_type,document_number,document_date,status,reason)
 values('issue','DEMO-DIR-'||p_request_id::text,current_date,'draft',left('DEMO Direct Issue '||p_purpose,300)) returning document_id into v_doc;
 for v_el in select * from jsonb_array_elements(p_lines) loop
  v_code:=v_el->>'item_code';
  if v_code not in ('DEMO_MOSQUITO','DEMO_GLYPHOSATE','DEMO_LAMBDA','DEMO_COMPOUND_D') then raise exception 'Only DEMO products allowed';end if;
  if (v_el->>'quantity') is null or (v_el->>'quantity') !~ '^[0-9]+(\.[0-9]+)?$' then raise exception 'Invalid quantity';end if;
  v_qty:=(v_el->>'quantity')::numeric;
  if v_qty<=0 or v_qty>10000 then raise exception 'Quantity out of range';end if;
  select item_id into v_item from stock_v2.item where item_code=v_code and active=true;
  if v_item is null then raise exception 'Demo product missing';end if;
  select coalesce(sum(quantity),0) into v_before from stock_v2.quantity_balance where item_id=v_item and owner_id=v_owner and location_id=v_loc;
  if v_before<v_qty then raise exception 'Insufficient demo stock for %: available %, requested %',v_code,v_before,v_qty;end if;
  insert into stock_v2.document_line(document_id,item_id,quantity,note) values(v_doc,v_item,v_qty,'TEST direct issue') returning line_id into v_line;
  insert into stock_v2.movement(document_line_id,owner_id,location_id,quantity_delta,external_tracecode_id)
  values(v_line,v_owner,v_loc,-v_qty,p_tracecode_id);
  v_result:=v_result||jsonb_build_array(jsonb_build_object('item_code',v_code,'quantity',v_qty));
 end loop;
 perform stock_v2.post_draft(v_doc);
 insert into stock_v2.demo_issue_request(request_id,document_id) values(p_request_id,v_doc);
 return jsonb_build_object('document_id',v_doc,'duplicate',false,'issued',v_result);
end $function$

CREATE OR REPLACE FUNCTION stock_v2.demo_post_combined_grv(p_request uuid, p_data jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'stock_v2'
AS $function$
declare own bigint; gid bigint; lid bigint; itm bigint; src bigint; newdoc bigint; result jsonb; oldres record;
rowdata jsonb; v_cost record; v_cost_run bigint; v_po record; v_po_qty numeric; v_po_count numeric; v_invoice text;v_supplier text;v_qty numeric;v_price numeric;v_code text;v_status text:='matched';v_request uuid;
begin
 if p_request is null or jsonb_typeof(p_data)<>'object' then raise exception 'Invalid request';end if;
 perform pg_advisory_xact_lock(hashtext('stock_v2_inventory_posting'));
 select wr.action,wr.result into oldres from stock_v2.demo_workflow_requests wr where wr.request_id=p_request;
 if found then
  if oldres.action<>'combined_grv' then raise exception 'Request identifier already used';end if;
  return oldres.result||jsonb_build_object('replayed',true);
 end if;
 select owner_id into own from stock_v2.owner where owner_code='TEST_'||coalesce(p_data->>'owner_code','') and active;
 if own is null then raise exception 'Unknown demo owner';end if;
 v_supplier:=nullif(btrim(p_data->>'supplier'),'');
 v_invoice:=nullif(btrim(p_data->>'invoice_number'),'');
 if v_supplier is null or v_invoice is null or nullif(p_data->>'invoice_date','') is null then raise exception 'Supplier and invoice details required';end if;
 if jsonb_typeof(p_data->'invoice_lines')<>'array' or jsonb_array_length(p_data->'invoice_lines')<1
 or jsonb_typeof(p_data->'allocations')<>'array'
 or jsonb_typeof(p_data->'new_receipts')<>'array' then raise exception 'Invoice lines, allocations and new receipts arrays required';end if;
 if jsonb_array_length(p_data->'new_receipts')=0 and jsonb_array_length(p_data->'allocations')=0 then raise exception 'No physical receipts selected';end if;
 insert into stock_v2.accounting_grv(owner_id,supplier_name,invoice_number,invoice_date)
 values(own,v_supplier,v_invoice,(p_data->>'invoice_date')::date) returning id into gid;
 for rowdata in select value from jsonb_array_elements(p_data->'invoice_lines') loop
  v_code:=rowdata->>'item_code';v_qty:=(rowdata->>'invoice_quantity')::numeric;v_price:=(rowdata->>'unit_price')::numeric;
  if v_qty is null or v_qty<=0 or v_price is null or v_price<=0 then raise exception 'Invalid invoice quantities or prices';end if;
  select item_id into itm from stock_v2.item where item_code=v_code and active;
  if itm is null then raise exception 'Unknown or inactive item %',v_code;end if;
  insert into stock_v2.accounting_grv_line(grv_id,item_id,invoice_quantity,invoice_unit_price)
  values(gid,itm,v_qty,v_price);
 end loop;
 -- Direct GRV PO allocations are mandatory and must match physical receipt quantities.
 if jsonb_typeof(p_data->'po_allocations') is distinct from 'array' then
   if jsonb_array_length(p_data->'new_receipts')>0 then raise exception 'PO allocations required for direct receipts';end if;
 end if;
 for rowdata in select value from jsonb_array_elements(coalesce(p_data->'po_allocations','[]'::jsonb)) loop
  if coalesce((rowdata->>'quantity')::numeric,0)<=0 then raise exception 'Direct PO quantity must be positive';end if;
  select ol.order_line_id,ol.item_id,ol.ordered_quantity,ol.received_quantity,h.owner_id,h.supplier_name,h.status,i.item_code
  into v_po from stock_v2.order_line ol join stock_v2.order_header h on h.order_id=ol.order_id
  join stock_v2.item i on i.item_id=ol.item_id
  where ol.order_line_id=(rowdata->>'order_line_id')::bigint for update of ol;
  if not found or v_po.owner_id<>own or lower(btrim(v_po.supplier_name))<>lower(btrim(v_supplier))
    or v_po.status<>'approved' or v_po.item_code<>rowdata->>'item_code'
    or v_po.received_quantity+(rowdata->>'quantity')::numeric>v_po.ordered_quantity
  then raise exception 'Invalid or exceeded supplier PO line';end if;
 end loop;
 if exists(
  select 1 from jsonb_array_elements(p_data->'new_receipts') x
  where (x->>'quantity')::numeric<>coalesce(
    (select sum((a->>'quantity')::numeric) from jsonb_array_elements(coalesce(p_data->'po_allocations','[]'::jsonb)) a
     where a->>'item_code'=x->>'item_code'),0)
 ) then raise exception 'PO line quantities do not match direct stock receipts';end if;
 if exists(
  select 1 from jsonb_array_elements(coalesce(p_data->'po_allocations','[]'::jsonb)) a
  where not exists(select 1 from jsonb_array_elements(p_data->'new_receipts') x where x->>'item_code'=a->>'item_code')
 ) then raise exception 'PO allocation has no matching direct receipt';end if;
 if jsonb_array_length(p_data->'new_receipts')>0 then
  v_request:=md5(p_request::text||':new-receipt')::uuid;
  select stock_v2.demo_multi('direct_grv',v_request,jsonb_build_object(
   'owner_code',p_data->>'owner_code','supplier',v_supplier,
   'receipt_mode','dnote','delivery_note','COMBINED-'||p_request::text,
   'receipt_date',coalesce(p_data->>'receipt_date',p_data->>'invoice_date'),
   'lines',p_data->'new_receipts')) into result;
  newdoc:=(result->>'document_id')::bigint;
 end if;
 -- Apply direct GRV quantities to the selected approved PO line(s) in the same transaction.
 if newdoc is not null then
 for rowdata in select value from jsonb_array_elements(coalesce(p_data->'po_allocations','[]'::jsonb)) loop
  update stock_v2.order_line
   set received_quantity=received_quantity+(rowdata->>'quantity')::numeric
   where order_line_id=(rowdata->>'order_line_id')::bigint;
  insert into stock_v2.demo_grv_order_link(document_id,order_line_id,qty,received_unit_price)
  values(newdoc,(rowdata->>'order_line_id')::bigint,(rowdata->>'quantity')::numeric,
    (select l.invoice_unit_price from stock_v2.accounting_grv_line l
     join stock_v2.item i on i.item_id=l.item_id where l.grv_id=gid and i.item_code=rowdata->>'item_code'));
 end loop;
 end if;
 for rowdata in
  select value from jsonb_array_elements(p_data->'allocations')
  union all
  select jsonb_build_object('line_id',line_id,'quantity',quantity)
  from stock_v2.document_line where document_id=newdoc
 loop
  src:=(rowdata->>'line_id')::bigint;v_qty:=(rowdata->>'quantity')::numeric;
  if src is null or v_qty is null or v_qty<=0 then raise exception 'Invalid receipt allocation';end if;
  select item_id into itm from stock_v2.document_line where line_id=src;
  select id into lid from stock_v2.accounting_grv_line where grv_id=gid and item_id=itm;
  if lid is null then raise exception 'Receipt product missing from invoice';end if;
  insert into stock_v2.accounting_grv_allocation(grv_line_id,receipt_line_id,quantity) values(lid,src,v_qty);
 end loop;
 -- Final GRVs must match all allocated physical quantities exactly.
 if exists(select 1 from stock_v2.accounting_grv_line l where l.grv_id=gid
 and l.invoice_quantity<>coalesce((select sum(a.quantity) from stock_v2.accounting_grv_allocation a where a.grv_line_id=l.id),0))
 then raise exception 'Final GRV quantity must match selected physical receipt quantities';end if;
 -- Never reprice an existing receipt line and never permit partially priced source lines.
 for v_cost in
  select a.receipt_line_id,dl.document_id,dl.quantity,al.item_id,al.invoice_unit_price
  from stock_v2.accounting_grv_allocation a
  join stock_v2.accounting_grv_line al on al.id=a.grv_line_id
  join stock_v2.document_line dl on dl.line_id=a.receipt_line_id
  where al.grv_id=gid
 loop
  if (select coalesce(sum(quantity),0) from stock_v2.accounting_grv_allocation where receipt_line_id=v_cost.receipt_line_id)
     <>v_cost.quantity then raise exception 'Final GRV requires full DNote line allocation';end if;
  if exists(select 1 from stock_v2.price_confirmation where line_id=v_cost.receipt_line_id)
  then raise exception 'Receipt already has a final price';end if;
  insert into stock_v2.price_confirmation(line_id,confirmed_unit_cost,invoice_number)
  values(v_cost.receipt_line_id,v_cost.invoice_unit_price,v_invoice);
  update stock_v2.grv_detail set invoice_number=v_invoice,invoice_date=(p_data->>'invoice_date')::date,price_status='confirmed'
  where document_id=v_cost.document_id
  and not exists(select 1 from stock_v2.document_line dl2 where dl2.document_id=v_cost.document_id
    and not exists(select 1 from stock_v2.price_confirmation pc where pc.line_id=dl2.line_id));
 end loop;
 for v_cost in select distinct item_id from stock_v2.accounting_grv_line where grv_id=gid loop
   v_cost_run:=stock_v2.recalculate_demo_item_costs(v_cost.item_id,'Combined GRV '||v_invoice);
 end loop;
 if exists(select 1 from stock_v2.accounting_grv_line l where l.grv_id=gid and l.invoice_quantity<>
   coalesce((select sum(a.quantity) from stock_v2.accounting_grv_allocation a where a.grv_line_id=l.id),0)) then
  v_status:='disputed';
 end if;
 update stock_v2.accounting_grv set status=v_status where id=gid;
 result:=jsonb_build_object('kind','combined_grv','grv_id',gid,'status',v_status,'new_receipt_document_id',newdoc);
 insert into stock_v2.demo_workflow_requests(request_id,action,result) values(p_request,'combined_grv',result);
 return result;
end $function$

CREATE OR REPLACE FUNCTION stock_v2.demo_manage(p_action text, p_data jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'stock_v2'
AS $function$
declare rid bigint; cid bigint; code text; result jsonb;
begin
 if p_action='save_contract' then
 code:=btrim(p_data->>'contract_code');
 if length(code)<1 or length(code)>40 then raise exception 'Contract code required (max 40)';end if;
 if nullif(btrim(p_data->>'contract_name'),'') is null then raise exception 'Contract name required';end if;
 cid:=nullif(p_data->>'contract_id','')::bigint;
 if cid is null then
 insert into stock_v2.contracts(contract_code,contract_name,active) values(code,btrim(p_data->>'contract_name'),coalesce((p_data->>'active')::boolean,true)) returning contract_id into cid;
 else
 update stock_v2.contracts set contract_code=code,contract_name=btrim(p_data->>'contract_name'),active=coalesce((p_data->>'active')::boolean,true) where contract_id=cid;
 if not found then raise exception 'Contract not found';end if;
 end if;
 return jsonb_build_object('contract_id',cid);
 elsif p_action='save_owner' then
 code:=upper(btrim(p_data->>'owner_code'));
 if code !~ '^[A-Z0-9_]{2,20}$' then raise exception 'Owner code must be 2-20 letters, numbers or underscores';end if;
 if nullif(btrim(p_data->>'owner_name'),'') is null then raise exception 'Owner name required';end if;
 rid:=nullif(p_data->>'owner_id','')::bigint;
 if rid is null then
 insert into stock_v2.owner(owner_code,owner_name,active) values('TEST_'||code,btrim(p_data->>'owner_name'),coalesce((p_data->>'active')::boolean,true)) returning owner_id into rid;
 else
 update stock_v2.owner set owner_name=btrim(p_data->>'owner_name'),active=coalesce((p_data->>'active')::boolean,true) where owner_id=rid and owner_code='TEST_'||code;
 if not found then raise exception 'Test owner not found; code cannot be changed';end if;
 end if;
 cid:=nullif(p_data->>'default_contract_id','')::bigint;
 if cid is not null and not exists(select 1 from stock_v2.contracts where contract_id=cid) then raise exception 'Default contract not found';end if;
 insert into stock_v2.owner_policy(owner_id,po_required_for_grv,po_requires_contract,default_contract_id,allow_direct_grv)
 values(rid,coalesce((p_data->>'po_required_for_grv')::boolean,false),coalesce((p_data->>'po_requires_contract')::boolean,false),cid,coalesce((p_data->>'allow_direct_grv')::boolean,false))
 on conflict(owner_id) do update set po_required_for_grv=excluded.po_required_for_grv,po_requires_contract=excluded.po_requires_contract,default_contract_id=excluded.default_contract_id,allow_direct_grv=excluded.allow_direct_grv;
 return jsonb_build_object('owner_id',rid);
 elsif p_action='save_trace_contract' then
 rid:=(p_data->>'tracecode_id')::bigint;cid:=(p_data->>'contract_id')::bigint;
 if not exists(select 1 from public.tracecode where tracecode_id=rid) then raise exception 'TraceCode not found';end if;
 if not exists(select 1 from stock_v2.contracts where contract_id=cid and active) then raise exception 'Active contract required';end if;
 insert into stock_v2.tracecode_contract(external_tracecode_id,contract_id) values(rid,cid)
 on conflict(external_tracecode_id) do update set contract_id=excluded.contract_id,assigned_at=now();
 return jsonb_build_object('tracecode_id',rid,'contract_id',cid);
 else raise exception 'Unknown management action';end if;
end $function$

CREATE OR REPLACE FUNCTION stock_v2.demo_edit_spray(p_job_id bigint, p_data jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'stock_v2'
AS $function$
declare j stock_v2.spray_job%rowtype; own bigint; trarea numeric; area numeric; line jsonb; code text; itemid bigint; n int:=0; names text[]:=array[]::text[]; resultlines jsonb:='[]'::jsonb;
begin
 perform pg_advisory_xact_lock(hashtext('stock_v2_inventory_posting'));
 select owner_id into own from stock_v2.owner where owner_code='TEST_JS';
 select * into j from stock_v2.spray_job where job_id=p_job_id and owner_id=own for update;
 if not found or j.status<>'planned' then raise exception 'Editable planned spray not found';end if;
 if exists(select 1 from stock_v2.spray_job_input ji join stock_v2.document_line dl on dl.requirement_id=ji.requirement_id join stock_v2.document d on d.document_id=dl.document_id where ji.job_id=p_job_id and d.document_type='issue' and d.status='posted') then raise exception 'Cannot edit spray once any product has been issued';end if;
 if jsonb_typeof(p_data->'lines')<>'array' or jsonb_array_length(p_data->'lines') not between 1 and 30 then raise exception 'Provide 1–30 inputs';end if;
 area:=nullif(p_data->>'area_ha','')::numeric;
 select tracecode_size into trarea from public.tracecode where tracecode_id=coalesce(nullif(p_data->>'tracecode_id','')::bigint,j.external_tracecode_id);
 if area is null or area<=0 or area>trarea then raise exception 'Invalid spray hectares';end if;
 if not exists(select 1 from stock_v2.access_spray_type_catalog where spray_type_name=p_data->>'spray_type') then raise exception 'Choose a valid spray type';end if;
 if nullif(p_data->>'water_rate','')::numeric<=0 then raise exception 'Water rate must be positive';end if;
 update stock_v2.spray_job set external_tracecode_id=coalesce(nullif(p_data->>'tracecode_id','')::bigint,j.external_tracecode_id),job_tracking_code=nullif(p_data->>'job_tracking_code',''),planned_week_start=coalesce(nullif(p_data->>'planned_week_start','')::date,planned_week_start),area_ha=area,part_label=coalesce(nullif(p_data->>'part_label',''),part_label),spray_type=p_data->>'spray_type',setup_id=(select setup_id from stock_v2.sprayer_setup where setup_name=p_data->>'spray_type' and active limit 1),water_litres_per_ha=(p_data->>'water_rate')::numeric,sprayer_asset_code=nullif(p_data->>'sprayer_asset_code','') where job_id=p_job_id;
 delete from stock_v2.spray_job_input where job_id=p_job_id;
 for line in select value from jsonb_array_elements(p_data->'lines') loop
  code:=line->>'item_code';
  if code is null or length(code)=0 then raise exception 'Choose a product';end if;
  if code=any(names) then raise exception 'Duplicate input %',code;end if;
  names:=array_append(names,code);
  select item_id into itemid from stock_v2.item where item_code=code and active;
  if itemid is null or (line->>'rate_per_ha')::numeric<=0 then raise exception 'Invalid input or rate';end if;
  insert into stock_v2.spray_job_input(job_id,item_id,rate_per_ha) values(p_job_id,itemid,(line->>'rate_per_ha')::numeric);
  n:=n+1;resultlines:=resultlines||jsonb_build_array(jsonb_build_object('item_code',code));
 end loop;
 return jsonb_build_object('job_id',p_job_id,'lines',resultlines);
end $function$

CREATE OR REPLACE FUNCTION stock_v2.demo_match_invoice(p_document bigint, p_invoice text, p_invoice_date date, p_lines jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'stock_v2'
AS $function$
declare hdr record; l record; x jsonb; n integer:=0; touched bigint[]:=array[]::bigint[]; price numeric; inv text; recost_item bigint; cost_run_id bigint; cost_runs jsonb:='[]'::jsonb; cost_pending jsonb:='[]'::jsonb;
begin
 perform pg_advisory_xact_lock(hashtext('stock_v2_inventory_posting'));
 inv:=nullif(btrim(p_invoice),'');
 if inv is null or p_invoice_date is null then raise exception 'Invoice number and invoice date required'; end if;
 select src.document_id,src.status,g.price_status into hdr from stock_v2.document src join stock_v2.grv_detail g using(document_id)
 where src.document_id=p_document and src.document_type='grv' and src.document_number like 'DEMO-%' for update of src;
 if not found or hdr.status<>'posted' or hdr.price_status<>'pending' then raise exception 'Outstanding posted DNote required';end if;
 if not exists(select 1 from stock_v2.document_line dl
   join stock_v2.movement m on m.document_line_id=dl.line_id
   join stock_v2.owner o on o.owner_id=m.owner_id
   join stock_v2.location loc on loc.location_id=m.location_id
   where dl.document_id=p_document and m.quantity_delta>0
     and o.owner_code in ('TEST_JS','TEST_AO') and loc.location_code='TEST_WH')
   then raise exception 'Only isolated TEST_JS or TEST_AO receipts may be priced';end if;
 if jsonb_typeof(p_lines)<>'array' or jsonb_array_length(p_lines)=0 then raise exception 'All receipt lines need invoice prices';end if;
 if jsonb_array_length(p_lines)<>(select count(*) from stock_v2.document_line where document_id=p_document) then raise exception 'Prices required for every received product';end if;
 for l in select line_id,item_id from stock_v2.document_line where document_id=p_document order by line_id loop
  select value into x from jsonb_array_elements(p_lines) where (value->>'line_id')::bigint=l.line_id;
  if x is null then raise exception 'Missing price for line %',l.line_id;end if;
  price:=nullif(x->>'unit_price','')::numeric;
  if price is null or price<=0 then raise exception 'Positive actual purchase price required for line %',l.line_id;end if;
  if exists(select 1 from stock_v2.price_confirmation where line_id=l.line_id) then raise exception 'Line already priced';end if;
  insert into stock_v2.price_confirmation(line_id,confirmed_unit_cost,invoice_number) values(l.line_id,price,inv);
  update stock_v2.demo_grv_line_link x set received_unit_price=price
  from stock_v2.order_line ol where x.document_id=p_document and x.order_line_id=ol.order_line_id and ol.item_id=l.item_id;
  update stock_v2.demo_grv_order_link x set received_unit_price=price
  from stock_v2.order_line ol where x.document_id=p_document and x.order_line_id=ol.order_line_id and ol.item_id=l.item_id;
  touched:=array_append(touched,l.item_id);n:=n+1;
 end loop;
 update stock_v2.grv_detail set invoice_number=inv,invoice_date=p_invoice_date,price_status='confirmed' where document_id=p_document;
 for recost_item in select distinct unnest(touched) loop
  begin
    cost_run_id:=stock_v2.recalculate_demo_item_costs(recost_item,'Invoice '||inv||' DNote '||p_document);
    cost_runs:=cost_runs||jsonb_build_array(jsonb_build_object('item_id',recost_item,'run_id',cost_run_id));
  exception when others then
    cost_pending:=cost_pending||jsonb_build_array(jsonb_build_object('item_id',recost_item,'reason',sqlerrm));
  end;
 end loop;
 return jsonb_build_object('document_id',p_document,'priced_lines',n,'invoice_number',inv,'cost_runs',cost_runs,'cost_pending',cost_pending);
end $function$

CREATE OR REPLACE FUNCTION stock_v2.recalculate_demo_item_costs(p_item_id bigint, p_reason text)
 RETURNS bigint
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'stock_v2'
AS $function$
declare r record; q numeric; v numeric; wa numeric; unit_price numeric; mv numeric; rk bigint; provisional_flag boolean; from_mov bigint;
begin
 perform pg_advisory_xact_lock(hashtext('stock_v2_inventory_posting'));
 if not exists(select 1 from stock_v2.item where item_id=p_item_id and active) then raise exception 'Demo products only';end if;
 insert into stock_v2.cost_run(reason,status) values(p_reason,'running') returning run_id into rk;
 for r in
 select m.movement_id,m.quantity_delta,m.owner_id,dl.item_id,dl.line_id,dl.source_line_id,d.document_type,d.document_id,d.document_date,
   coalesce(pc.confirmed_unit_cost,gp.actual_unit_cost) actual_cost,gp.provisional_unit_cost,
   (select m2.movement_id from stock_v2.movement m2 where m2.document_line_id=dl.line_id and m2.quantity_delta<0 limit 1) source_transfer_movement
 from stock_v2.movement m join stock_v2.document_line dl on dl.line_id=m.document_line_id
 join stock_v2.document d on d.document_id=dl.document_id
 left join stock_v2.grv_line_price gp on gp.line_id=dl.line_id
 left join stock_v2.price_confirmation pc on pc.line_id=dl.line_id
 where d.status='posted' and dl.item_id=p_item_id
 order by d.document_date,d.document_id,case when d.document_type='ownership_transfer' and m.quantity_delta<0 then 0 else 1 end,m.movement_id
 loop
 select coalesce(sum(mm.quantity_delta),0),coalesce(sum(ce.movement_value),0) into q,v
 from stock_v2.cost_entry ce
 join stock_v2.movement mm on mm.movement_id=ce.movement_id
 where ce.run_id=rk and ce.owner_id=r.owner_id;
 q:=coalesce(q,0);v:=coalesce(v,0);
 wa:=case when q>0 then v/q else null end;
 provisional_flag:=false;
 if r.document_type in ('opening','grv') then
  unit_price:=coalesce(r.actual_cost,r.provisional_unit_cost,wa,10::numeric);
  if unit_price is null then raise exception 'Opening or GRV cost missing for line % (owner %)',r.line_id,r.owner_id;end if;
  provisional_flag:=r.actual_cost is null;
 elsif r.document_type='ownership_transfer' and r.quantity_delta>0 then
  select ce.unit_cost into unit_price from stock_v2.cost_entry ce
  where ce.run_id=rk and ce.movement_id=r.source_transfer_movement;
  if unit_price is null then raise exception 'Source transfer cost missing for line %',r.line_id;end if;
 elsif r.document_type='return' then
  select ce.unit_cost into unit_price from stock_v2.cost_entry ce
  join stock_v2.movement m2 on m2.movement_id=ce.movement_id
  join stock_v2.document_line dl2 on dl2.line_id=m2.document_line_id
  where ce.run_id=rk and dl2.line_id=r.source_line_id and m2.owner_id=r.owner_id and m2.quantity_delta<0 limit 1;
  unit_price:=coalesce(unit_price,wa);
  if unit_price is null then raise exception 'Return cost missing for line %',r.line_id;end if;
 else
  unit_price:=wa;
  if unit_price is null then raise exception 'WA cost unavailable for issue or adjustment line %',r.line_id;end if;
 end if;
 if q+r.quantity_delta < -0.000001 then raise exception 'Negative stock in historical replay for movement %',r.movement_id;end if;
 mv:=r.quantity_delta*unit_price;
 insert into stock_v2.cost_entry(run_id,movement_id,item_id,owner_id,quantity_after,value_after,unit_cost,movement_value,provisional)
 values(rk,r.movement_id,r.item_id,r.owner_id,q+r.quantity_delta,v+mv,unit_price,mv,provisional_flag);
 end loop;
 update stock_v2.cost_run set status='complete',finished_at=now() where run_id=rk;
 return rk;
end $function$

CREATE OR REPLACE FUNCTION stock_v2.accounting_grv_check_allocation()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'stock_v2'
AS $function$
declare h record; r record; already numeric;
begin
 perform pg_advisory_xact_lock(hashtext('stock_v2_inventory_posting'));
 select g.owner_id,g.supplier_name,g.status,l.item_id into h from stock_v2.accounting_grv_line l
 join stock_v2.accounting_grv g on g.id=l.grv_id where l.id=new.grv_line_id for update of g;
 if not found or h.status not in ('draft','disputed') then raise exception 'GRV is not editable';end if;
 select dl.item_id,dl.quantity,d.status,gd.supplier_name,m.owner_id into r
 from stock_v2.document_line dl join stock_v2.document d on d.document_id=dl.document_id
 join stock_v2.grv_detail gd on gd.document_id=d.document_id
 join stock_v2.movement m on m.document_line_id=dl.line_id and m.quantity_delta>0
 where dl.line_id=new.receipt_line_id and d.document_number like 'DEMO-%' for update of dl;
 if not found or r.item_id<>h.item_id or r.owner_id<>h.owner_id or r.status<>'posted'
 or lower(btrim(r.supplier_name))<>lower(btrim(h.supplier_name)) then
 raise exception 'Receipt supplier, owner, product or status mismatch';end if;
 select coalesce(sum(a.quantity),0) into already from stock_v2.accounting_grv_allocation a
 where a.receipt_line_id=new.receipt_line_id and a.id<>coalesce(new.id,-1);
 if already+new.quantity>r.quantity then raise exception 'Receipt quantity exceeded';end if;
 return new;
end $function$

CREATE OR REPLACE FUNCTION stock_v2.demo_save_credit_note(p_grv bigint, p_number text, p_date date, p_reason text, p_lines jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'stock_v2'
AS $function$
declare v_id bigint;v_row jsonb;v_item bigint;v_qty numeric;v_amount numeric;v_count int:=0;
begin
 perform pg_advisory_xact_lock(hashtext('stock_v2_inventory_posting'));
 if not exists(select 1 from stock_v2.accounting_grv where id=p_grv and status in ('matched','disputed','draft')) then raise exception 'Editable accounting GRV required';end if;
 if nullif(btrim(p_number),'') is null or p_date is null or nullif(btrim(p_reason),'') is null then raise exception 'Credit note number, date and reason required';end if;
 if jsonb_typeof(p_lines)<>'array' or jsonb_array_length(p_lines)<1 then raise exception 'Credit note products required';end if;
 insert into stock_v2.accounting_grv_credit_note(grv_id,credit_note_number,credit_note_date,reason)
 values(p_grv,btrim(p_number),p_date,btrim(p_reason)) returning id into v_id;
 for v_row in select value from jsonb_array_elements(p_lines) loop
  select item_id into v_item from stock_v2.item where item_code=v_row->>'item_code' and item_code like 'DEMO_%';
  if v_item is null or not exists(select 1 from stock_v2.accounting_grv_line where grv_id=p_grv and item_id=v_item) then raise exception 'Credit product is not on GRV';end if;
  v_qty:=(v_row->>'quantity')::numeric;v_amount:=(v_row->>'amount')::numeric;
  if v_qty is null or v_amount is null or v_qty<0 or v_amount<=0 then raise exception 'Invalid credit quantity or amount';end if;
  insert into stock_v2.accounting_grv_credit_line(credit_note_id,item_id,quantity,amount) values(v_id,v_item,v_qty,v_amount);
  v_count:=v_count+1;
 end loop;
 return jsonb_build_object('credit_note_id',v_id,'status','draft','lines',v_count);
end $function$

CREATE OR REPLACE FUNCTION stock_v2.demo_request_admin_correction(p_kind text, p_target bigint, p_action text, p_reason text, p_values jsonb, p_actor uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'stock_v2'
AS $function$
declare v_id bigint;
begin
 if p_kind not in ('dnote','invoice','grv','credit_note') or p_action not in ('edit','disregard','reopen') or p_target is null or p_target<=0 or nullif(btrim(p_reason),'') is null then raise exception 'Invalid correction request';end if;
 if p_actor is null then raise exception 'Authenticated actor required';end if;
 if p_kind='credit_note' and not exists(select 1 from stock_v2.accounting_grv_credit_note where id=p_target) then raise exception 'Credit note not found';end if;
 if p_kind in ('invoice','grv') and not exists(select 1 from stock_v2.accounting_grv where id=p_target) then raise exception 'Accounting GRV not found';end if;
 if p_kind='dnote' and not exists(select 1 from stock_v2.document where document_id=p_target and document_type='grv' and document_number like 'DEMO-%') then raise exception 'Demo DNote not found';end if;
 insert into stock_v2.accounting_grv_admin_request(target_kind,target_id,requested_action,reason,proposed_values,requested_by)
 values(p_kind,p_target,p_action,btrim(p_reason),p_values,p_actor) returning id into v_id;
 return jsonb_build_object('request_id',v_id,'status','pending');
end $function$

CREATE OR REPLACE FUNCTION stock_v2.demo_confirm_credit_note(p_credit_note_id bigint, p_actor uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'stock_v2'
AS $function$
declare v_grv bigint;v_total numeric;v_credited numeric;v_invoice numeric;v_status text;
begin
 if p_actor is null or not exists(select 1 from stock_v2.staff_role where user_id=p_actor and active and lower(role_name) in ('admin','administrator')) then raise exception 'Active Stock V2 Admin access required';end if;
 perform pg_advisory_xact_lock(hashtext('stock_v2_inventory_posting'));
 select grv_id,status into v_grv,v_status from stock_v2.accounting_grv_credit_note where id=p_credit_note_id for update;
 if not found or v_status<>'draft' then raise exception 'Only draft credit notes may be confirmed';end if;
 select coalesce(sum(invoice_quantity*invoice_unit_price),0) into v_invoice from stock_v2.accounting_grv_line where grv_id=v_grv;
 select coalesce(sum(cl.amount),0) into v_credited from stock_v2.accounting_grv_credit_line cl join stock_v2.accounting_grv_credit_note cn on cn.id=cl.credit_note_id where cn.grv_id=v_grv and cn.status='confirmed';
 select coalesce(sum(amount),0) into v_total from stock_v2.accounting_grv_credit_line where credit_note_id=p_credit_note_id;
 if v_total<=0 or v_total+v_credited>v_invoice then raise exception 'Credit exceeds invoice value';end if;
 update stock_v2.accounting_grv_credit_note set status='confirmed' where id=p_credit_note_id;
 return jsonb_build_object('credit_note_id',p_credit_note_id,'status','confirmed','credited_total',v_total,'invoice_balance',v_invoice-v_total-v_credited);
end $function$
